      "id": 1,
      "claim": "The two ships are identical in design, propulsion, and hull; they differ only in cargo mass.",
      "evidence": "Problem statement says the ships are identical except for the weight of cargo they carry.",
      "weight": 0.2,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "The maximum braking force (reverse thrust plus hydrodynamic drag) that can be applied is the same for both ships.",
      "evidence": "Because the propulsion and hull are identical, cargo weight does not affect the thrust‑producing machinery or the water‑resistance characteristics at a given speed.",
      "weight": 0.2,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "The heavy‑cargo ship has a larger total mass than the light‑cargo ship.",
      "evidence": "Cargo adds directly to the ship’s mass; heavier cargo ⇒ greater total mass.",
      "weight": 0.15,
      "depends_on": [1]
    },
    {
      "id": 4,
      "claim": "Both ships travel at the same initial speed v.",
      "evidence": "Explicitly given in the problem.",
      "weight": 0.1,
      "depends_on": []
    },
    {
      "id": 5,
      "claim": "The heavy ship’s initial momentum p = m v is greater than the light ship’s momentum.",
      "evidence": "Momentum definition p = m v; with v equal (step 4) and m heavier (step 3), p_heavy > p_light.",
      "weight": 0.15,
      "depends_on": [3, 4]
    },
    {
      "id": 6,
      "claim": "For a constant average braking force, stopping time Δt = Δp / F (impulse‑momentum theorem).",
      "evidence": "Newton’s second law in impulse form: F Δt = Δp ⇒ Δt = Δp / F.",
      "weight": 0.1,
      "depends_on": []
    },
    {
      "id": 7,
      "claim": "Because the heavy ship has larger Δp and the braking force F is the same, its stopping time Δt is larger.",
      "evidence": "Combine steps 5 (larger Δp), 2 (same F), and 6 (Δt proportional to Δp/F).",
      "weight": 0.1,
      "depends_on": [5, 2, 6]
    }
  ],
  "answer": "B",
  "confidence": 0.99,
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "Increased friction would increase the decelerating force, which would shorten, not lengthen, the stopping time."
    },
    {
      "answer": "C",
      "reason_rejected": "Greater (de)acceleration means a larger magnitude of negative acceleration, which would reduce the stopping time, opposite to the observed effect."
    },
    {
      "answer": "D",
      "reason_rejected": "Constant velocity describes the initial motion; it does not cause a difference in stopping time."
    }
